{
  "results": [
    {
      "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/das-core/",
      "title": "Fulu -- Data Availability Sampling Core",
      "category": "consensus-spec",
      "type": "Specification",
      "status": "Active",
      "layer": "consensus",
      "sub_graphs": [
        {
          "id": "SG-DAS-CORE-TYPES",
          "name": "DAS Core Type Aliases",
          "description": "Defines the core type aliases used throughout the DAS specification for indexing rows, columns, and custody groups in the extended data matrix.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-TYPES-001",
              "text": "RowIndex, ColumnIndex, and CustodyIndex are all uint64 aliases. They MUST be used consistently for type safety when referring to matrix rows, columns, and custody groups respectively."
            }
          ],
          "functions": [],
          "state_variables": [
            {
              "id": "SV-DAS-CORE-TYPES-001",
              "name": "RowIndex",
              "type": "uint64",
              "description": "Row identifier in the matrix of cells."
            },
            {
              "id": "SV-DAS-CORE-TYPES-002",
              "name": "ColumnIndex",
              "type": "uint64",
              "description": "Column identifier in the matrix of cells."
            },
            {
              "id": "SV-DAS-CORE-TYPES-003",
              "name": "CustodyIndex",
              "type": "uint64",
              "description": "Custody group identifier in the set of custody groups."
            }
          ],
          "data_structures": [],
          "pre_conditions": [],
          "post_conditions": [],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-CONSTANTS",
          "name": "DAS Core Constants and Configuration",
          "description": "Defines the non-configurable constants, preset size parameters, and configurable custody settings that govern the DAS system geometry and sampling behavior.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-CONSTANTS-001",
              "text": "UINT256_MAX equals uint256(2**256 - 1) and is used as an overflow guard in custody group computation."
            },
            {
              "id": "INV-DAS-CORE-CONSTANTS-002",
              "text": "NUMBER_OF_COLUMNS equals uint64(CELLS_PER_EXT_BLOB) which is 128. This defines the fixed width of the extended data matrix."
            },
            {
              "id": "INV-DAS-CORE-CONSTANTS-003",
              "text": "NUMBER_OF_CUSTODY_GROUPS is 128. This is the total number of custody groups available for node assignment."
            },
            {
              "id": "INV-DAS-CORE-CONSTANTS-004",
              "text": "CUSTODY_REQUIREMENT is 4. Every honest node MUST custody at least this many custody groups."
            },
            {
              "id": "INV-DAS-CORE-CONSTANTS-005",
              "text": "SAMPLES_PER_SLOT is 8. This is the minimum number of custody groups an honest node must sample per slot."
            },
            {
              "id": "INV-DAS-CORE-CONSTANTS-006",
              "text": "NUMBER_OF_COLUMNS MUST be evenly divisible by NUMBER_OF_CUSTODY_GROUPS to ensure uniform column distribution across custody groups. Currently 128 / 128 = 1 column per group."
            }
          ],
          "functions": [],
          "state_variables": [
            {
              "id": "SV-DAS-CORE-CONSTANTS-001",
              "name": "UINT256_MAX",
              "type": "uint256",
              "value": "uint256(2**256 - 1)",
              "description": "Maximum uint256 value, used for overflow prevention in get_custody_groups."
            },
            {
              "id": "SV-DAS-CORE-CONSTANTS-002",
              "name": "NUMBER_OF_COLUMNS",
              "type": "uint64",
              "value": "uint64(CELLS_PER_EXT_BLOB) = 128",
              "description": "Number of columns in the extended data matrix."
            },
            {
              "id": "SV-DAS-CORE-CONSTANTS-003",
              "name": "SAMPLES_PER_SLOT",
              "type": "uint64",
              "value": "8",
              "description": "Minimum number of samples for an honest node per slot."
            },
            {
              "id": "SV-DAS-CORE-CONSTANTS-004",
              "name": "NUMBER_OF_CUSTODY_GROUPS",
              "type": "uint64",
              "value": "128",
              "description": "Number of custody groups available for nodes to custody."
            },
            {
              "id": "SV-DAS-CORE-CONSTANTS-005",
              "name": "CUSTODY_REQUIREMENT",
              "type": "uint64",
              "value": "4",
              "description": "Minimum number of custody groups an honest node custodies and serves samples from."
            }
          ],
          "data_structures": [],
          "pre_conditions": [],
          "post_conditions": [],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-DATA-COLUMN-SIDECAR",
          "name": "DataColumnSidecar Container",
          "description": "Defines the DataColumnSidecar container which encapsulates a single column of extended blob data along with its KZG commitments, proofs, associated block header, and an inclusion proof. This is the primary data structure distributed over the gossip network for data availability.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-DCS-001",
              "text": "Each DataColumnSidecar index MUST correspond to a valid ColumnIndex in the range [0, NUMBER_OF_COLUMNS)."
            },
            {
              "id": "INV-DAS-CORE-DCS-002",
              "text": "The length of column, kzg_commitments, and kzg_proofs lists MUST all be equal and MUST NOT exceed MAX_BLOB_COMMITMENTS_PER_BLOCK."
            },
            {
              "id": "INV-DAS-CORE-DCS-003",
              "text": "The kzg_commitments_inclusion_proof MUST be a valid Merkle proof of depth KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH linking the kzg_commitments to the signed_block_header."
            }
          ],
          "functions": [],
          "state_variables": [],
          "data_structures": [
            {
              "id": "DS-DAS-CORE-DCS-001",
              "name": "DataColumnSidecar",
              "kind": "Container",
              "fields": [
                {
                  "name": "index",
                  "type": "ColumnIndex",
                  "description": "The column index this sidecar represents."
                },
                {
                  "name": "column",
                  "type": "List[Cell, MAX_BLOB_COMMITMENTS_PER_BLOCK]",
                  "description": "The cells for this column, one per blob in the block."
                },
                {
                  "name": "kzg_commitments",
                  "type": "List[KZGCommitment, MAX_BLOB_COMMITMENTS_PER_BLOCK]",
                  "description": "The KZG commitments corresponding to each blob."
                },
                {
                  "name": "kzg_proofs",
                  "type": "List[KZGProof, MAX_BLOB_COMMITMENTS_PER_BLOCK]",
                  "description": "The KZG proofs for each cell in the column."
                },
                {
                  "name": "signed_block_header",
                  "type": "SignedBeaconBlockHeader",
                  "description": "The signed beacon block header this column belongs to."
                },
                {
                  "name": "kzg_commitments_inclusion_proof",
                  "type": "Vector[Bytes32, KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH]",
                  "description": "Merkle inclusion proof for the KZG commitments in the block."
                }
              ]
            }
          ],
          "pre_conditions": [],
          "post_conditions": [],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-MATRIX-ENTRY",
          "name": "MatrixEntry Container",
          "description": "Defines the MatrixEntry container, which represents a single element in the extended data matrix. Each entry contains a cell, its KZG proof, and its position (column, row) in the matrix. This is the fundamental unit for matrix computation and recovery.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-ME-001",
              "text": "Each MatrixEntry column_index MUST be in the range [0, NUMBER_OF_COLUMNS)."
            },
            {
              "id": "INV-DAS-CORE-ME-002",
              "text": "Each MatrixEntry row_index MUST be in the range [0, MAX_BLOBS_PER_BLOCK)."
            },
            {
              "id": "INV-DAS-CORE-ME-003",
              "text": "The kzg_proof in a MatrixEntry MUST be valid with respect to the corresponding cell, column_index, and the KZG commitment for the blob at row_index."
            }
          ],
          "functions": [],
          "state_variables": [],
          "data_structures": [
            {
              "id": "DS-DAS-CORE-ME-001",
              "name": "MatrixEntry",
              "kind": "Container",
              "fields": [
                {
                  "name": "cell",
                  "type": "Cell",
                  "description": "The cell data for this matrix position."
                },
                {
                  "name": "kzg_proof",
                  "type": "KZGProof",
                  "description": "The KZG proof for this cell."
                },
                {
                  "name": "column_index",
                  "type": "ColumnIndex",
                  "description": "Column position in the extended data matrix."
                },
                {
                  "name": "row_index",
                  "type": "RowIndex",
                  "description": "Row position in the extended data matrix (corresponds to blob index)."
                }
              ]
            }
          ],
          "pre_conditions": [],
          "post_conditions": [],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-GET-CUSTODY-GROUPS",
          "name": "Custody Group Selection (get_custody_groups)",
          "description": "Implements the deterministic, public custody group selection algorithm. Given a node ID and a desired number of custody groups, it computes which custody groups the node is responsible for using a hash-based pseudo-random selection. The selection is stable: increasing custody_group_count extends the existing set rather than reshuffling.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-GCG-001",
              "text": "The returned custody groups MUST contain exactly custody_group_count unique CustodyIndex values."
            },
            {
              "id": "INV-DAS-CORE-GCG-002",
              "text": "All returned CustodyIndex values MUST be in the range [0, NUMBER_OF_CUSTODY_GROUPS)."
            },
            {
              "id": "INV-DAS-CORE-GCG-003",
              "text": "The returned list MUST be sorted in ascending order."
            },
            {
              "id": "INV-DAS-CORE-GCG-004",
              "text": "The selection is deterministic: the same (node_id, custody_group_count) inputs MUST always produce the same output."
            },
            {
              "id": "INV-DAS-CORE-GCG-005",
              "text": "Increasing custody_group_count for a given node_id MUST produce a superset of the previously returned groups (monotonic extension property)."
            }
          ],
          "functions": [
            {
              "id": "FN-DAS-CORE-GCG-001",
              "name": "get_custody_groups",
              "signature": "def get_custody_groups(node_id: NodeID, custody_group_count: uint64) -> Sequence[CustodyIndex]",
              "description": "Deterministically computes which custody groups a node with the given node_id should custody, based on hash(uint_to_bytes(current_id)) modulo NUMBER_OF_CUSTODY_GROUPS. Handles overflow by wrapping current_id from UINT256_MAX to 0.",
              "parameters": [
                {
                  "name": "node_id",
                  "type": "NodeID",
                  "description": "The public node identifier used to seed the pseudo-random selection."
                },
                {
                  "name": "custody_group_count",
                  "type": "uint64",
                  "description": "The number of custody groups to select. Must be <= NUMBER_OF_CUSTODY_GROUPS."
                }
              ],
              "returns": "Sequence[CustodyIndex] - a sorted list of unique custody group indices",
              "body": "def get_custody_groups(node_id: NodeID, custody_group_count: uint64) -> Sequence[CustodyIndex]:\n    assert custody_group_count <= NUMBER_OF_CUSTODY_GROUPS\n\n    # Skip computation if all groups are custodied\n    if custody_group_count == NUMBER_OF_CUSTODY_GROUPS:\n        return [CustodyIndex(i) for i in range(NUMBER_OF_CUSTODY_GROUPS)]\n\n    current_id = uint256(node_id)\n    custody_groups: List[CustodyIndex] = []\n    while len(custody_groups) < custody_group_count:\n        custody_group = CustodyIndex(\n            bytes_to_uint64(hash(uint_to_bytes(current_id))[0:8]) % NUMBER_OF_CUSTODY_GROUPS\n        )\n        if custody_group not in custody_groups:\n            custody_groups.append(custody_group)\n        if current_id == UINT256_MAX:\n            # Overflow prevention\n            current_id = uint256(0)\n        else:\n            current_id += 1\n\n    assert len(custody_groups) == len(set(custody_groups))\n    return sorted(custody_groups)"
            }
          ],
          "state_variables": [],
          "data_structures": [],
          "pre_conditions": [
            {
              "id": "PRE-DAS-CORE-GCG-001",
              "text": "custody_group_count MUST be <= NUMBER_OF_CUSTODY_GROUPS (128)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-DAS-CORE-GCG-001",
              "text": "The returned list has exactly custody_group_count elements."
            },
            {
              "id": "POST-DAS-CORE-GCG-002",
              "text": "All elements in the returned list are unique (no duplicates)."
            },
            {
              "id": "POST-DAS-CORE-GCG-003",
              "text": "The returned list is sorted in ascending order."
            }
          ],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-COMPUTE-COLUMNS-FOR-CUSTODY-GROUP",
          "name": "Column-to-Custody-Group Mapping (compute_columns_for_custody_group)",
          "description": "Computes the set of column indices that belong to a given custody group. Columns are interleaved across custody groups using a stride pattern: group g gets columns {g, g + NUMBER_OF_CUSTODY_GROUPS, g + 2*NUMBER_OF_CUSTODY_GROUPS, ...}. With NUMBER_OF_COLUMNS=128 and NUMBER_OF_CUSTODY_GROUPS=128, each group currently maps to exactly 1 column.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-CCFCG-001",
              "text": "Each column index in the returned sequence MUST be in the range [0, NUMBER_OF_COLUMNS)."
            },
            {
              "id": "INV-DAS-CORE-CCFCG-002",
              "text": "The returned columns MUST be exactly columns_per_group = NUMBER_OF_COLUMNS // NUMBER_OF_CUSTODY_GROUPS columns."
            },
            {
              "id": "INV-DAS-CORE-CCFCG-003",
              "text": "The union of compute_columns_for_custody_group(g) for all g in [0, NUMBER_OF_CUSTODY_GROUPS) MUST equal the set of all columns [0, NUMBER_OF_COLUMNS). Every column belongs to exactly one custody group."
            },
            {
              "id": "INV-DAS-CORE-CCFCG-004",
              "text": "Column assignment is deterministic and uses an interleaving pattern: column c belongs to custody group c % NUMBER_OF_CUSTODY_GROUPS."
            }
          ],
          "functions": [
            {
              "id": "FN-DAS-CORE-CCFCG-001",
              "name": "compute_columns_for_custody_group",
              "signature": "def compute_columns_for_custody_group(custody_group: CustodyIndex) -> Sequence[ColumnIndex]",
              "description": "Returns the list of column indices assigned to the given custody group using an interleaving stride of NUMBER_OF_CUSTODY_GROUPS.",
              "parameters": [
                {
                  "name": "custody_group",
                  "type": "CustodyIndex",
                  "description": "The custody group index to look up columns for."
                }
              ],
              "returns": "Sequence[ColumnIndex] - the column indices belonging to this custody group",
              "body": "def compute_columns_for_custody_group(custody_group: CustodyIndex) -> Sequence[ColumnIndex]:\n    assert custody_group < NUMBER_OF_CUSTODY_GROUPS\n    columns_per_group = NUMBER_OF_COLUMNS // NUMBER_OF_CUSTODY_GROUPS\n    return [\n        ColumnIndex(NUMBER_OF_CUSTODY_GROUPS * i + custody_group) for i in range(columns_per_group)\n    ]"
            }
          ],
          "state_variables": [],
          "data_structures": [],
          "pre_conditions": [
            {
              "id": "PRE-DAS-CORE-CCFCG-001",
              "text": "custody_group MUST be < NUMBER_OF_CUSTODY_GROUPS (128)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-DAS-CORE-CCFCG-001",
              "text": "Returned sequence has exactly NUMBER_OF_COLUMNS // NUMBER_OF_CUSTODY_GROUPS elements."
            }
          ],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-COMPUTE-MATRIX",
          "name": "Matrix Computation (compute_matrix)",
          "description": "Computes the full extended data matrix from a sequence of blobs. Each blob is expanded into cells and KZG proofs via compute_cells_and_kzg_proofs, producing a flattened sequence of MatrixEntry objects. The matrix has blob_count rows and NUMBER_OF_COLUMNS columns.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-CM-001",
              "text": "The returned matrix MUST contain exactly len(blobs) * NUMBER_OF_COLUMNS entries."
            },
            {
              "id": "INV-DAS-CORE-CM-002",
              "text": "For each MatrixEntry, row_index == blob_index and column_index == cell_index within that blob's expansion."
            },
            {
              "id": "INV-DAS-CORE-CM-003",
              "text": "Each (row_index, column_index) pair in the returned matrix MUST be unique."
            }
          ],
          "functions": [
            {
              "id": "FN-DAS-CORE-CM-001",
              "name": "compute_matrix",
              "signature": "def compute_matrix(blobs: Sequence[Blob]) -> Sequence[MatrixEntry]",
              "description": "Computes the full, flattened sequence of matrix entries from input blobs. Iterates over each blob, calls compute_cells_and_kzg_proofs to get cells and proofs, then creates a MatrixEntry for each (blob_index, cell_index) pair.",
              "parameters": [
                {
                  "name": "blobs",
                  "type": "Sequence[Blob]",
                  "description": "The input blobs to be extended into the data matrix."
                }
              ],
              "returns": "Sequence[MatrixEntry] - the full flattened matrix",
              "body": "def compute_matrix(blobs: Sequence[Blob]) -> Sequence[MatrixEntry]:\n    \"\"\"\n    Return the full, flattened sequence of matrix entries.\n\n    This helper demonstrates the relationship between blobs and the matrix of cells/proofs.\n    The data structure for storing cells/proofs is implementation-dependent.\n    \"\"\"\n    matrix = []\n    for blob_index, blob in enumerate(blobs):\n        cells, proofs = compute_cells_and_kzg_proofs(blob)\n        for cell_index, (cell, proof) in enumerate(zip(cells, proofs)):\n            matrix.append(\n                MatrixEntry(\n                    cell=cell,\n                    kzg_proof=proof,\n                    column_index=cell_index,\n                    row_index=blob_index,\n                )\n            )\n    return matrix"
            }
          ],
          "state_variables": [],
          "data_structures": [],
          "pre_conditions": [
            {
              "id": "PRE-DAS-CORE-CM-001",
              "text": "Each blob in the input sequence MUST be a valid Blob that can be processed by compute_cells_and_kzg_proofs."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-DAS-CORE-CM-001",
              "text": "The output contains len(blobs) * NUMBER_OF_COLUMNS MatrixEntry objects."
            },
            {
              "id": "POST-DAS-CORE-CM-002",
              "text": "Every entry has a valid KZG proof for its cell at the given (row_index, column_index)."
            }
          ],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-RECOVER-MATRIX",
          "name": "Matrix Recovery (recover_matrix)",
          "description": "Recovers the full extended data matrix from a partial set of matrix entries using erasure coding recovery. For each blob row, it collects available cells and their column indices, then calls recover_cells_and_kzg_proofs to reconstruct missing cells. Requires at least 50% of columns per row for successful recovery.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-RM-001",
              "text": "The output MUST contain exactly blob_count * NUMBER_OF_COLUMNS entries after successful recovery."
            },
            {
              "id": "INV-DAS-CORE-RM-002",
              "text": "All recovered cells and proofs MUST be valid and consistent with the original KZG commitments."
            },
            {
              "id": "INV-DAS-CORE-RM-003",
              "text": "Recovery requires at least 50% of columns (NUMBER_OF_COLUMNS / 2) to be present for each blob row in the partial_matrix."
            }
          ],
          "functions": [
            {
              "id": "FN-DAS-CORE-RM-001",
              "name": "recover_matrix",
              "signature": "def recover_matrix(partial_matrix: Sequence[MatrixEntry], blob_count: uint64) -> Sequence[MatrixEntry]",
              "description": "Recovers the full flattened matrix from a partial matrix. For each blob index [0, blob_count), filters partial_matrix entries by row_index, extracts cell_indices and cells, then calls recover_cells_and_kzg_proofs to reconstruct all cells and proofs for that row.",
              "parameters": [
                {
                  "name": "partial_matrix",
                  "type": "Sequence[MatrixEntry]",
                  "description": "A partial set of matrix entries, must have >= 50% of columns per blob row."
                },
                {
                  "name": "blob_count",
                  "type": "uint64",
                  "description": "The number of blobs (rows) in the matrix."
                }
              ],
              "returns": "Sequence[MatrixEntry] - the fully recovered flattened matrix",
              "body": "def recover_matrix(\n    partial_matrix: Sequence[MatrixEntry], blob_count: uint64\n) -> Sequence[MatrixEntry]:\n    \"\"\"\n    Recover the full, flattened sequence of matrix entries.\n\n    This helper demonstrates how to apply ``recover_cells_and_kzg_proofs``.\n    The data structure for storing cells/proofs is implementation-dependent.\n    \"\"\"\n    matrix = []\n    for blob_index in range(blob_count):\n        cell_indices = [e.column_index for e in partial_matrix if e.row_index == blob_index]\n        cells = [e.cell for e in partial_matrix if e.row_index == blob_index]\n        recovered_cells, recovered_proofs = recover_cells_and_kzg_proofs(cell_indices, cells)\n        for cell_index, (cell, proof) in enumerate(zip(recovered_cells, recovered_proofs)):\n            matrix.append(\n                MatrixEntry(\n                    cell=cell,\n                    kzg_proof=proof,\n                    column_index=cell_index,\n                    row_index=blob_index,\n                )\n            )\n    return matrix"
            }
          ],
          "state_variables": [],
          "data_structures": [],
          "pre_conditions": [
            {
              "id": "PRE-DAS-CORE-RM-001",
              "text": "For each blob_index in [0, blob_count), at least 50% of columns (>= NUMBER_OF_COLUMNS / 2) MUST be present in partial_matrix for that row."
            },
            {
              "id": "PRE-DAS-CORE-RM-002",
              "text": "All MatrixEntry objects in partial_matrix MUST have valid cells and column_index values."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-DAS-CORE-RM-001",
              "text": "The output contains exactly blob_count * NUMBER_OF_COLUMNS MatrixEntry objects."
            },
            {
              "id": "POST-DAS-CORE-RM-002",
              "text": "Every recovered entry has a valid KZG proof."
            }
          ],
          "state_transitions": []
        },
        {
          "id": "SG-DAS-CORE-CUSTODY-PROTOCOL",
          "name": "Custody Protocol Requirements",
          "description": "Defines the behavioral requirements for node custody including mandatory custody obligations, optional extended custody, custody sampling per slot, and how sampling integrates with the custody group selection function.",
          "invariants": [
            {
              "id": "INV-DAS-CORE-CP-001",
              "text": "Nodes MUST custody all columns in each of their assigned custody groups. Partial custody of a group is not permitted."
            },
            {
              "id": "INV-DAS-CORE-CP-002",
              "text": "A node's custody groups are a deterministic function of (node_id, custody_group_count), computable by any party since all inputs are public."
            },
            {
              "id": "INV-DAS-CORE-CP-003",
              "text": "When syncing, a node MUST backfill columns from all of its custody groups."
            },
            {
              "id": "INV-DAS-CORE-CP-004",
              "text": "A node stores custodied columns for the duration of the pruning period."
            },
            {
              "id": "INV-DAS-CORE-CP-005",
              "text": "A node MUST respond to peer requests for samples on custodied columns."
            },
            {
              "id": "INV-DAS-CORE-CP-006",
              "text": "A node advertising custody_group_count via ENR downloads at each slot a minimum of sampling_size = max(SAMPLES_PER_SLOT, custody_group_count) custody groups."
            },
            {
              "id": "INV-DAS-CORE-CP-007",
              "text": "The custody groups to custody (get_custody_groups(node_id, custody_group_count)) MUST be a subset of the groups to sample (get_custody_groups(node_id, sampling_size)), due to the monotonic extension property."
            },
            {
              "id": "INV-DAS-CORE-CP-008",
              "text": "Sampling is considered successful if and only if the node manages to retrieve ALL selected columns."
            }
          ],
          "functions": [],
          "state_variables": [],
          "data_structures": [],
          "pre_conditions": [],
          "post_conditions": [],
          "state_transitions": [
            {
              "id": "ST-DAS-CORE-CP-001",
              "description": "Per-slot sampling: node computes groups = get_custody_groups(node_id, max(SAMPLES_PER_SLOT, custody_group_count)), expands each group to columns via compute_columns_for_custody_group, then attempts to retrieve all columns. Success requires all columns retrieved."
            }
          ]
        },
        {
          "id": "SG-DAS-CORE-RECONSTRUCTION",
          "name": "Reconstruction and Cross-Seeding Protocol",
